const F=(id,c)=>[id,c];
const S=[
["Introducción e indicaciones","pulse",[
["Qué es el eFAST",["El FAST original (Focused Abdominal Sonogram for Trauma, Rozycki 1996) tenía 3 vistas: cuadrante superior derecho, cuadrante superior izquierdo y pelvis, para descartar sangrado abdominal por trauma.","En 2004, Kirkpatrick y col. propusieron el eFAST (Extended Focused Assessment with Sonography in Trauma), que suma la evaluación de los pulmones y del corazón. Surgió de estudios de los años 90 y 2000 que mostraron la utilidad de la ecografía para neumotórax (Lichtenstein), hemoperitoneo (Kimura) y derrame pericárdico (Plummer) en urgencias.","Hoy el eFAST explora abdomen, pulmones y corazón. Permite hacer el protocolo completo en 5 pasos, evaluar líquido libre intraabdominal o intratorácico, sospecha de taponamiento y sospecha de neumotórax."]],
["Indicaciones",["Paciente con trauma inestable hemodinámicamente","Trauma abdominal y torácico, cerrado o penetrante","Paciente con trauma antes estable que empeora clínicamente"]],
["Limitaciones",["No localiza qué órgano abdominal se lesionó","Las vistas pueden ser limitadas con enfisema subcutáneo","Las vistas pueden ser limitadas con lesión de víscera hueca y aire libre en el abdomen"]],
["Aviso",["La fuente está pensada para adultos. En lactantes y niños hay que ajustar la sonda, la profundidad y la ganancia. Las cifras de sensibilidad y especificidad son de población adulta."]]
]],
["Preparación y secuencia","list",[
["Paciente",["Decúbito supino, con la camilla plana o en Trendelenburg (aumenta la sensibilidad, pero no es obligatorio)."],[F(3,"Equipo de ecografía y posición del paciente")]],
["Equipo",["Sonda: la sectorial (phased array, o sonda cardíaca) sirve para todo el examen. La convexa también se puede usar, pero las vistas cardíacas son más difíciles por su gran superficie de contacto.","Preset: FAST o abdominal.","Ubicación del equipo: a la derecha del paciente. Así se explora con la mano derecha y se manejan los controles con la izquierda."]],
["Secuencia recomendada",["Hay muchas secuencias en la literatura. Elegí una y hacela siempre igual para no olvidar ninguna vista. La que recomienda la fuente:","1. Cuadrante superior derecho","2. Cuadrante superior izquierdo","3. Pelvis","4. Corazón (paraesternal eje largo o subxifoidea)","5. Pulmones (derecho e izquierdo)"],[F(4,"Secuencia recomendada del eFAST (rótulos originales en inglés: RUQ = cuadrante superior derecho, LUQ = izquierdo, Pelvis, Cardiac = corazón, Lungs = pulmones)")]],
["Las 4 preguntas del eFAST",["¿Hay líquido libre en el abdomen?","¿Hay líquido libre en el tórax?","¿Hay líquido en el pericardio?","¿Hay neumotórax?"]]
]],
["Paso 1: cuadrante superior derecho","pulse",[
["Pregunta",["¿Hay líquido libre en el abdomen o en el tórax derecho? En esta vista y en la del lado izquierdo hay que buscar líquido por encima del diafragma (hemotórax) y por debajo (hemoperitoneo).","Como el hígado es el órgano que más se lesiona en el trauma abdominal cerrado, esta suele ser la vista más sensible del eFAST."]],
["Posición de la sonda",["Indicador hacia la cabeza del paciente.","Anclar la sonda en la línea axilar media, a la altura del 10.º espacio intercostal."],[F(5,"Posición de la sonda en el cuadrante superior derecho"),F(6,"Detalle de la sonda en el cuadrante superior derecho. La flecha roja marca la orientación del indicador")]],
["Vista normal y estructuras",["Con el hígado como ventana acústica se identifican: pulmón, hígado, espacio de Morison, diafragma y riñón derecho en eje largo.","El espacio de Morison es donde habitualmente se ve el líquido libre en esta vista.","El artefacto en espejo es normal: indica que hay pulmón aireado por encima del diafragma.","Puede hacer falta deslizar la sonda hacia arriba o hacia abajo un espacio intercostal."],[F(7,"Cuadrante superior derecho normal: hígado, espacio de Morison, riñón derecho, diafragma y pulmón (artefacto en espejo). HEAD = cabeza, FOOT = pies"),F(9,"Esquema superpuesto: pulmón, diafragma, hígado y riñón")]],
["Consejos",["Las estructuras se mueven con los movimientos del diafragma en la respiración: se puede pedir al paciente que contenga la respiración.","Rotar levemente la sonda en sentido antihorario hacia la camilla para que entre mejor entre las costillas."]]
]],
["Paso 2: cuadrante superior izquierdo","pulse",[
["Pregunta",["¿Hay líquido libre en el abdomen o en el tórax izquierdo?"]],
["Posición de la sonda",["Agarrar la sonda entre el pulgar y el índice, como un lápiz.","Indicador hacia la cabeza del paciente.","Anclar en la línea axilar posterior, alrededor del 8.º espacio intercostal.","Con los nudillos hacia la camilla, porque el bazo es bastante posterior."],[F(10,"Posición de la sonda en el cuadrante superior izquierdo"),F(11,"Nudillos hacia la camilla en la vista del cuadrante superior izquierdo. La flecha roja marca la orientación del indicador")]],
["Vista normal y estructuras",["Con el bazo como ventana acústica se identifican: bazo, espacio periesplénico, diafragma y riñón izquierdo en eje largo.","El líquido libre en esta vista se ve con más frecuencia en el espacio periesplénico (entre el bazo y el diafragma), porque un ligamento esplenorrenal limita que el líquido pase entre el bazo y el riñón izquierdo.","El artefacto en espejo también es normal acá.","Puede hacer falta subir o bajar un espacio intercostal."],[F(12,"Cuadrante superior izquierdo normal: bazo, riñón izquierdo, diafragma y pulmón (artefacto en espejo)"),F(14,"Esquema superpuesto: pulmón, diafragma, bazo y riñón")]],
["Consejos",["Las estructuras se mueven con la respiración: se puede pedir apnea.","Rotar levemente la sonda en sentido horario hacia la camilla para que entre mejor entre las costillas."]]
]],
["Paso 3: pelvis","pulse",[
["Pregunta y preparación",["¿Hay líquido libre en el abdomen o en la pelvis?","Hay que considerar el sexo del paciente: el líquido libre se acumula en lugares distintos. Además, las mujeres pueden tener una pequeña cantidad de líquido fisiológico en el fondo de saco de Douglas.","Idealmente, con la vejiga llena (se usa como ventana acústica): intentar el examen antes de colocar la sonda vesical.","Profundidad de la máquina: 10–15 cm."]],
["Pelvis: corte longitudinal",["Sonda con el indicador hacia la cabeza, en la línea media, justo por encima de la sínfisis del pubis.","Inclinar la sonda para que apunte hacia la cavidad pélvica.","Consejo: la vejiga está inmediatamente por detrás del pubis. Si no lográs buenas imágenes, lo más probable es que la sonda esté demasiado alta."],[F(15,"Corte longitudinal de la pelvis: posición de la sonda"),F(16,"Esquema: apuntar la sonda hacia la pelvis (vejiga detrás del pubis)")]],
["Varones",["Identificar la vejiga (inmediatamente por detrás de la sínfisis), la próstata y las vesículas seminales, y el fondo de saco rectovesical.","El fondo de saco rectovesical es donde se acumula el líquido libre en la pelvis masculina."],[F(17,"Pelvis masculina, corte longitudinal: vejiga, próstata y espacio retrovesical"),F(19,"Ilustración de la pelvis masculina: fondo de saco rectovesical")]],
["Mujeres",["Identificar la vejiga, el útero y el fondo de saco rectouterino (de Douglas).","El fondo de saco de Douglas es donde se acumula el líquido libre en la pelvis femenina."],[F(20,"Pelvis femenina, corte longitudinal: vejiga, útero, recto y gas intestinal"),F(22,"Ilustración de la pelvis femenina: fondo de saco rectouterino (de Douglas)")]],
["Todos los pacientes",["Observar los bordes laterales de la vejiga inclinando o abanicando la sonda hacia la izquierda y hacia la derecha para buscar líquido libre."],[F(23,"Inclinación de la sonda en el corte longitudinal")]],
["Pelvis: corte transversal",["Centrar la vejiga y rotar la sonda 90° en sentido antihorario: el indicador queda hacia el lado derecho del paciente.","Inclinar la sonda para explorar hacia la cavidad pélvica.","Identificar vejiga, útero (mujeres) o próstata (varones) y recto.","Abanicar la sonda para recorrer toda la pelvis de arriba hacia abajo."],[F(24,"Corte transversal de la pelvis: posición de la sonda"),F(25,"Pelvis femenina, corte transversal: vejiga, útero y recto"),F(26,"Pelvis masculina, corte transversal: vejiga, próstata y recto"),F(27,"Corte transversal con inclinación de la sonda")]]
]],
["Paso 4: corazón","heart",[
["Pregunta",["¿Hay derrame pericárdico con taponamiento?","La vista subxifoidea es la preferida para evaluar el corazón y el líquido pericárdico. Puede ser difícil de obtener (por ejemplo por la constitución del paciente o por dolor abdominal en el trauma). Si no se logra, se recomienda la paraesternal eje largo.","Nota del editor: en la guía el indicador se orienta según el preset abdominal/eFAST. Con el preset cardíaco, el indicador apunta 180° hacia el lado opuesto."]],
["Subxifoidea",["Sostener la sonda con la palma de la mano, con agarre desde arriba.","Indicador hacia la derecha del paciente, con la profundidad en alrededor de 15–20 cm.","Con el hígado como ventana acústica, presionar la sonda contra el abdomen y al mismo tiempo llevar la cola de la sonda hacia los pies del paciente.","Apuntar el haz hacia el hombro izquierdo del paciente.","Identificar hígado, pericardio, aurícula derecha, ventrículo derecho, aurícula izquierda y ventrículo izquierdo."],[F(28,"Posición de la sonda en la vista subxifoidea"),F(29,"Vista subxifoidea: hígado, pericardio, VD (ventrículo derecho), VI (ventrículo izquierdo), AD (aurícula derecha) y AI (aurícula izquierda)"),F(30,"Ilustración de la vista subxifoidea: AD, VD, AI, VI")]],
["Paraesternal eje largo",["Considerarla cuando no se obtiene la subxifoidea. Si no, pasar a los pulmones.","Agarrar la sonda entre el pulgar y el índice, como un lápiz.","Anclar los dedos medio y/o anular en el 2.º o 3.er espacio intercostal izquierdo, justo al costado del esternón.","Indicador hacia la cadera izquierda del paciente, con la profundidad en alrededor de 10–15 cm.","Identificar pericardio, válvula mitral, válvula aórtica, ventrículo derecho, aorta descendente, aurícula izquierda y ventrículo izquierdo. Puede hacer falta subir o bajar un espacio."],[F(31,"Posición de la sonda en la vista paraesternal eje largo"),F(32,"Paraesternal eje largo: VD, VI, AI, válvula aórtica, válvula mitral, pericardio y aorta descendente (DA)"),F(33,"Ilustración de la paraesternal eje largo")]]
]],
["Paso 5: pulmones","wind",[
["Pregunta",["¿Hay neumotórax? La pleura parietal cubre la superficie del tórax y la pleura visceral cubre el pulmón. Su movimiento una contra otra produce el deslizamiento pleural en la ecografía."]],
["Posición de la sonda",["Indicador hacia la cabeza del paciente.","Línea medioclavicular, en el 2.º espacio intercostal de los pulmones derecho e izquierdo. Es el punto más sensible para buscar neumotórax en el paciente en decúbito supino.","Anclar la sonda entre dos costillas y fijar la profundidad en 3–5 cm."],[F(34,"Pulmón derecho: posición de la sonda"),F(35,"Pulmón izquierdo: posición de la sonda")]],
["1.º Dos sombras costales (signo del murciélago)",["Es el primer hallazgo para confirmar que la sonda está bien ubicada: se ven dos sombras costales. Asegura que la sonda esté entre dos costillas."],[F(36,"Signo del murciélago, ilustración: tejido blando, costillas, pleura, líneas A, sombras costales y tejido pulmonar"),F(37,"Signo del murciélago en la ecografía: costilla y sombra costal a cada lado")]],
["2.º Deslizamiento pleural",["Es normal: las pleuras visceral y parietal se deslizan una sobre otra al respirar. Algunos lo describen como pequeñas “hormigas marchando sobre una línea”.","Es un hallazgo simple pero muy útil: el deslizamiento indica que las pleuras están una junto a la otra, lo que descarta neumotórax."],[F(38,"Deslizamiento pleural normal (modo B)")]],
["Deslizamiento en modo M (opcional)",["Si el deslizamiento no es evidente, se puede evaluar en modo M. El objetivo es ver el signo normal de la orilla del mar.","Poner la máquina en modo M y colocar el cursor sobre el campo pulmonar (no sobre una costilla).","Signo de la orilla del mar (normal): cielo = piel y tejido subcutáneo, océano = músculo, playa = movimiento del deslizamiento (aspecto arenoso).","Contrastarlo con el signo del código de barras (ver hallazgos patológicos)."],[F(39,"Pulmón normal con signo de la orilla del mar en modo M: cielo (Sky), océano (Ocean) y playa (Beach)")]]
]],
["Hallazgos patológicos","shield",[
["En general",["El líquido se ve negro (anecoico). En el eFAST se buscan zonas anecoicas en el abdomen, el tórax y el corazón, que indican sangrado en esos espacios.","Para el neumotórax se evalúa la presencia o ausencia de deslizamiento pleural."]],
["Hemoperitoneo",["El eFAST es moderadamente sensible (alrededor de 80%) y muy específico (>90%) para detectar líquido libre por hemoperitoneo. Se considera que hacen falta al menos 200–250 mL de sangre para que el examen sea positivo.","Ver líquido libre no localiza el sangrado en un órgano específico. Por ejemplo, líquido en la pelvis puede venir de cualquier parte del abdomen y no indica lesión de la vejiga. Para localizar el origen del sangrado abdominal en trauma se necesita una tomografía."]],
["Cuadrante superior derecho",["Los 3 lugares frecuentes donde se acumula líquido en el cuadrante superior derecho son:","Espacio hepatorrenal (espacio de Morison)","Punta caudal del hígado","Espacio suprahepático"],[F(41,"Espacio de Morison (línea punteada roja) en el esquema del cuadrante superior derecho"),F(42,"Líquido libre en la punta caudal del hígado"),F(43,"Líquido libre en el espacio de Morison y en el espacio suprahepático")]],
["Cuadrante superior izquierdo",["Se busca líquido libre en: espacio periesplénico, punta del bazo y receso esplenorrenal.","Consejo: en este cuadrante, el lugar más frecuente es el espacio periesplénico, no entre el bazo y el riñón izquierdo. Un ligamento esplenorrenal une el bazo y el riñón e impide que se acumule mucho líquido ahí, salvo que el ligamento esté roto."],[F(44,"Espacio periesplénico (línea punteada roja) en el esquema del cuadrante superior izquierdo"),F(45,"Líquido libre en el espacio periesplénico")]],
["Pelvis masculina",["En la pelvis masculina el líquido libre se encuentra en el fondo de saco rectovesical."],[F(46,"Fondo de saco rectovesical en la pelvis masculina"),F(47,"Líquido libre abdominal en la pelvis masculina (fondo de saco rectovesical)")]],
["Pelvis femenina",["En la pelvis femenina el líquido libre se encuentra en el fondo de saco de Douglas (rectouterino)."],[F(48,"Fondo de saco de Douglas en la pelvis femenina"),F(49,"Líquido libre abdominal en la pelvis femenina (fondo de saco de Douglas)")]],
["Hemotórax",["Después de evaluar el cuadrante superior derecho o izquierdo, mover la sonda uno o dos espacios hacia arriba para evaluar si hay líquido en el tórax.","Un pulmón normal tiene artefacto en espejo y no se ve la columna por encima del diafragma, porque todas las ondas son reflejadas por el pulmón aireado.","Ver la columna por encima del diafragma implica que hay líquido libre (por ejemplo sangre) en el tórax, porque las ondas atraviesan el líquido. Es el signo de la columna positivo."],[F(50,"Hallazgo normal: artefacto en espejo, sin columna visible sobre el diafragma"),F(52,"Hallazgo patológico: signo de la columna (Spine Sign)")]],
["Derrame pericárdico y taponamiento",["El líquido libre anecoico en el saco pericárdico es un derrame pericárdico.","Ver un derrame no significa que haya taponamiento: el líquido debe estar impidiendo el llenado cardíaco para considerarlo taponamiento.","Pensar en taponamiento cuando se observa:","Colapso sistólico de la aurícula derecha: el hallazgo ecocardiográfico más sensible y más precoz de taponamiento (también llamado signo del trampolín).","Colapso diastólico del ventrículo derecho: el hallazgo ecocardiográfico más específico de taponamiento (75–90%)."],[F(53,"Vista subxifoidea con derrame pericárdico"),F(54,"Paraesternal eje largo con derrame pericárdico y taponamiento (colapso diastólico del VD)")]],
["Neumotórax: 3 pasos",["1.º Si hay deslizamiento pleural, se descarta neumotórax en ese punto (según la fuente, con 100% de precisión; Husain). Se puede buscar en modo B o en modo M.","2.º Si el deslizamiento está AUSENTE, no asumir neumotórax de inmediato. Otras causas de deslizamiento reducido o ausente: consolidación grave, pleurodesis química, estados infecciosos o inflamatorios agudos, enfermedades pulmonares fibrosas, síndrome de dificultad respiratoria aguda (SDRA) e intubación selectiva de un bronquio principal.","Para el eFAST es muy probable que haya neumotórax si no se ve deslizamiento en modo B ni en modo M. Para confirmarlo, buscar el punto pulmonar.","3.º Si hay punto pulmonar, se confirma el neumotórax (según la fuente, con 100% de precisión; Chan). El punto pulmonar es la transición entre el pulmón con deslizamiento normal y sin deslizamiento: el límite entre el pulmón colapsado y el pulmón normal. También ayuda a estimar el tamaño del neumotórax.","Si dudás de haber encontrado el punto pulmonar, usar el modo M con el cursor en la zona donde parece empezar o terminar el deslizamiento: si se ve el signo de la orilla del mar que pasa a un código de barras anormal, se localizó el punto pulmonar."],[F(57,"Ausencia de deslizamiento pleural (modo B)"),F(58,"Ausencia de deslizamiento: signo del código de barras (modo M)"),F(59,"Signo del punto pulmonar (modo B)"),F(60,"Punto pulmonar en modo M")]],
["Neumoperitoneo",["En trauma (sobre todo penetrante) puede haber aire libre en la cavidad peritoneal.","El hallazgo más frecuente es el signo de la banda peritoneal aumentada (EPSS): el aire en el espacio peritoneal asciende y produce un “eco” de la banda peritoneal hiperecoica que normalmente es única y separa la pared abdominal del líquido peritoneal y de los órganos llenos de líquido (Indiran).","Con mucho aire, la imagen de los órganos abdominales queda oscurecida por el aire en cualquier lugar donde se apoye la sonda.","Consejo: si no se obtienen buenas vistas abdominales a pesar de tener la sonda bien ubicada, sospechar neumoperitoneo."],[F(62,"Signo de la banda peritoneal aumentada (flechas), anterior al hígado: aire entre el hígado y la pared abdominal")]]
]],
["Algoritmo y resumen","check",[
["Cuándo sirve más",["El eFAST es más útil en pacientes inestables hemodinámicamente que no pueden ir a la tomografía.","Un eFAST positivo ayuda al cirujano a identificar la región general del sangrado (abdomen, corazón o pulmones) para planificar el abordaje."]],
["Si el eFAST inicial es negativo",["Con un mecanismo de lesión muy sospechoso, puede convenir una tomografía o repetir el eFAST (seriados), sobre todo si empeora el estado clínico (signos vitales, inestabilidad hemodinámica, dolor o examen abdominal), porque la presentación puede ser tardía."]]
]]
];
const SUM=[
["Cuadrante superior derecho",["Sonda: línea axilar media, 10.º espacio intercostal, indicador a la cabeza","Mirar: espacio de Morison, punta caudal del hígado, espacio suprahepático","Además: columna visible sobre el diafragma = líquido en el tórax"]],
["Cuadrante superior izquierdo",["Sonda: línea axilar posterior, 8.º espacio intercostal, indicador a la cabeza, nudillos hacia la camilla","Mirar: espacio periesplénico (el más frecuente), punta del bazo, receso esplenorrenal"]],
["Pelvis",["Sonda: sobre la sínfisis del pubis, indicador a la cabeza, apuntando a la pelvis; luego rotar 90° en sentido antihorario","Mirar: fondo de saco rectovesical (varones) o de Douglas (mujeres) y bordes laterales de la vejiga. Profundidad 10–15 cm"]],
["Corazón",["Subxifoidea (preferida): indicador a la derecha del paciente con el preset abdominal, profundidad 15–20 cm, haz hacia el hombro izquierdo. Si no se logra, paraesternal eje largo (2.º o 3.er espacio intercostal izquierdo, indicador a la cadera izquierda, 10–15 cm)","Mirar: líquido pericárdico, colapso de la aurícula derecha (sístole) o del ventrículo derecho (diástole)"]],
["Pulmones",["Sonda: línea medioclavicular, 2.º espacio intercostal, ambos lados, profundidad 3–5 cm, indicador a la cabeza","Mirar: signo del murciélago, deslizamiento pleural (presente = sin neumotórax en ese punto). Si está ausente: buscar el punto pulmonar"]]
];
const NOTAS=[
["1. Subxifoidea",["Marca a la derecha, hígado; en apéndice xifoides, inclinar"]],
["2. Flanco derecho",["Marca arriba, línea medioaxilar y cruce con subxifoidea: ángulo costofrénico, riñón y Morrison (entre borde hepático y riñón derecho)","Líquido en Morrison = negro"]],
["3. Pleura derecha",["Igual pero más arriba, entre costillas, para ver pleura"]],
["4. Flanco izquierdo",["Línea axilar media, marca hacia arriba: ángulo periesplénico. Densidad del bazo igual a la del hígado. Negro = líquido","Después más arriba para ver pleura"]],
["5. Suprapúbica",["Marca a la derecha y luego rotar la marca hacia arriba","Espacio retrovesical (Douglas): que no tenga líquido"]]
];
const REFS=["Lobo V, Hunter-Behrend M, Cullnan E y col. Caudal Edge of the Liver in the RUQ View Is the Most Sensitive Area for Free Fluid on the FAST Exam. West J Emerg Med 2017;18(2):270-280.","Little WC, Freeman GL. Pericardial Disease. Circulation 2006;113:1622-32.","Jung H-O. Pericardial effusion and pericardiocentesis: role of echocardiography. Korean Circ J 2012;42:725-34.","emDocs. US Probe: When Does an Effusion Become Pericardial Tamponade? (consultado 28/6/2020).","Guntheroth WG. Sensitivity and specificity of echocardiographic evidence of tamponade: implications for ventricular interdependence and pulsus paradoxus. Pediatr Cardiol 2007;28(5):358-62.","Himelman RB y col. Inferior vena cava plethora with blunted respiratory response: a sensitive echocardiographic sign of cardiac tamponade. J Am Coll Cardiol 1988;12(6):1470-7.","Settle HP y col. Echocardiographic study of cardiac tamponade. Circulation 1977;56(6):951-9.","Perez-Casares A y col. Echocardiographic Evaluation of Pericardial Effusion and Cardiac Tamponade. Front Pediatr 2017;5:79.","Armstrong WF y col. Diastolic collapse of the right ventricle with cardiac tamponade. Circulation 1982;65(7):1491-6.","Singh S y col. Right ventricular and right atrial collapse in patients with cardiac tamponade. Circulation 1984;70(6):966-71.","Engel PJ y col. Echocardiographic study of right ventricular wall motion in cardiac tamponade. Am J Cardiol 1982;50(5):1018-21.","Kronzon I, Cohen ML, Winer HE. Diastolic atrial compression: a sensitive echocardiographic sign of cardiac tamponade. J Am Coll Cardiol 1983;2(4):770-5.","Rozycki GS, Shackford SR. Ultrasound, what every trauma surgeon should know. J Trauma 1996;40(1):1-4.","Ma OJ, Mateer JR. Trauma ultrasound examination versus chest radiography in the detection of hemothorax. Ann Emerg Med 1997;29(3):312-6.","Kimura A, Otsuka T. Emergency center ultrasonography in the evaluation of hemoperitoneum. J Trauma 1991;31(1):20-3.","Plummer D y col. Emergency department echocardiography improves outcome in penetrating cardiac injury. Ann Emerg Med 1992;21(6):709-12.","Lichtenstein DA, Menu Y. A bedside ultrasound sign ruling out pneumothorax in the critically ill. Lung sliding. Chest 1995;108(5):1345-8.","Kirkpatrick AW y col. Hand-held thoracic sonography for detecting post-traumatic pneumothoraces: the EFAST. J Trauma 2004;57(2):288-95.","Friedman LM, Tsung J. Extending the eFAST examination in children. 2011.","Richards J, McGahan J. Focused Assessment with Sonography in Trauma (FAST) in 2017: What Radiologists Can Learn. Radiology 2017;283(1):30-48."];
const fig=(f)=>`<figure class="us"><img src="${IMG[f[0]]}" alt="${f[1]}" loading="lazy"><figcaption>${f[1]}</figcaption></figure>`;
const blk=(it)=>`<div class="bk"><h3>${esc(it[0])}</h3>${it[1].map(l=>`<p>${esc(l)}</p>`).join("")}${(it[2]||[]).map(fig).join("")}</div>`;
const card=(id,t,ic_,n,body)=>`<details class="card" id="${id}"><summary><div class="sh"><span class="ic">${ic(ic_)}</span><b>${t}</b><span class="cnt">${n}</span>${ic("chev","chev")}</div></summary><div class="bb">${body}</div></details>`;
S.unshift(...[["Accesos vasculares ecoguiados", "pulse", [["Antes de puncionar: explorar y elegir", ["Explorar siempre antes de armar el campo estéril (si no es una urgencia extrema): tamaño, compresibilidad, variación respiratoria, trombos, hematomas y relación con la arteria. Primero corte transversal; luego girar 90° para el longitudinal.", "Vena: ovalada, irregular, se comprime con poca presión, varía con la respiración, flujo bifásico de baja velocidad. Arteria: redonda, pared gruesa, poco compresible, flujo sistólico de alta velocidad. Ambas pueden pulsar: no usar solo el pulso. El color rojo/azul del Doppler solo indica dirección del flujo, no distingue arteria de vena.", "Nunca canalizar una vena que no se comprime con el transductor (trombosis). Evitar la zona de hematoma y las venas con flaps o doble pared por punciones previas.", "Tamaño del catéter: grosor ≤ 1/3 del diámetro de la vena. 1 Fr = 0,33 mm. Regla práctica: diámetro de la vena en mm ≥ calibre del catéter en Fr (3 Fr necesita una vena de ≥3 mm). Para PICC, medir la vena antes de colocar el compresor.", "Posición: elegir la postura en que la arteria queda más separada de la vena y mantenerla durante todo el procedimiento. En neonatos y lactantes pequeños la VYI suele superponerse a la carótida (mayor riesgo de punción arterial). Evitar la rotación y extensión excesivas del cuello."], [["v_doppler", "Doppler pulsado: arterial (a, sistólico de alta velocidad) y venoso (b, baja velocidad bifásico)"], ["v_trombo", "Trombosis, hematoma y estenosis por daño de pared tras punciones repetidas"]]], ["Técnica general (eje corto y eje largo)", ["Alinear en una misma línea visual: sitio de punción, transductor y pantalla. Funda y gel estériles. Marca del transductor y marca de la pantalla coherentes.", "Fuera de plano (transversal): el vaso se ve como un círculo y la aguja como un punto hiperecogénico. Puncionar a ~45° a una distancia del transductor igual a la profundidad del vaso; seguir la punta basculando el transductor. Es el abordaje más usado y el mejor cuando falta espacio o el niño es pequeño.", "En plano (longitudinal u oblicuo): se ve toda la aguja y el vaso. No avanzar la aguja si no se ve en la pantalla. Es de elección si hay espacio y destreza. Cuidar que el ángulo de entrada no sea tan agudo como para que la guía choque con la pared posterior.", "Seldinger: tras la punción, comprobar con ecografía que la guía está dentro del vaso y va hacia el destino, en plano transversal y longitudinal (una guía en bucle se ve mejor en transversal). Solo avanzar el dilatador o el catéter con la guía confirmada.", "Trendelenburg (si la situación lo permite) aumenta el calibre de la vena yugular y reduce el riesgo de embolia gaseosa."], [["v_fuera", "VYI fuera de plano: posición del cuello y del transductor (a); aguja como punto hiperecogénico dentro del vaso (b)"], ["v_plano", "VYI en plano longitudinal: la aguja se ve en todo su trayecto"]]], ["Qué acceso elegir (sugerencias, no normas)", ["Neonato y lactante <5 kg, ventilación mecánica: elección tronco braquiocefálico (TBC) supraclavicular. Alternativas: VYI, femoral.", "Neonato y lactante <5 kg, respiración espontánea: elección TBC. Alternativas: femoral en plano, VYI.", "Niño pequeño, ventilación mecánica: VYI o TBC supraclavicular. Alternativas: femoral. En respiración espontánea: TBC; alternativas yugular o femoral.", "Niño mayor, ventilación mecánica: VYI fuera de plano; alternativas TBC y femoral. En respiración espontánea: VYI; alternativas TBC y femoral.", "Abordaje por vena: VYI fuera de plano (alternativa: longitudinal en plano cervical bajo u oblicuo en plano). TBC: longitudinal en plano. Subclavia: supraclavicular lateral en plano (alternativa: infraclavicular). Axilar: transversal o longitudinal en plano. Femoral: transversal (alternativa: longitudinal en plano).", "Protocolo RaCeVa (evaluación rápida de venas centrales): 1) VYI cuello medio, 2) VYI cuello distal, 3) TBC supraclavicular longitudinal, 4) subclavia supraclavicular, 5) subclavia/axilar infraclavicular transversal, 6) lo mismo longitudinal. En cada una: tamaño, permeabilidad, variación respiratoria, relación con la arteria y cercanía a la pleura."], []], ["Vena yugular interna (VYI)", ["Posición: a la cabecera, cabeza hacia el lado contrario. Transductor transversal en el vértice del triángulo de los dos fascículos del esternocleidomastoideo. Derecha: marca hacia medial. Izquierda: marca hacia lateral.", "En el 80–90% de los niños fuera del período neonatal la VYI está anterolateral a la carótida. La VYI derecha suele ser más grande y tiene un trayecto directo a la cava superior (menos malposición de la guía): preferida sobre la izquierda.", "El calibre aumenta hacia el tórax: la punción cervical baja da más éxito (longitudinal u oblicuo en plano si el tamaño lo permite).", "En el neonato se colapsa con presión mínima del transductor y se superpone a la carótida: es un acceso menos favorable."], [["v_vyi", "Corte transversal: vena (V) anterolateral y arteria (A) carótida"]]], ["Tronco braquiocefálico (TBC) y subclavia supraclavicular", ["Es la vena más gruesa accesible. Está fijada a estructuras vecinas: no se colapsa con la presión externa ni con la respiración, por eso es ideal en respiración espontánea o con distrés. Tasas de éxito >95% descritas incluso en neonatos de bajo peso. Se puede comprimir directamente si hay coagulopatía.", "Cómo llegar: transversal sobre la VYI, bajar por el cuello hasta la fosa supraclavicular, inclinar hacia anterior (aparece la arteria subclavia) y obtener el eje largo de la unión subclavia–TBC. Más lateral se ve la subclavia; más medial, solo el TBC.", "Aguja en plano, entrando por el lado lateral del transductor, viendo toda la aguja. Identificar siempre la línea pleural y el ápex pulmonar para no producir neumotórax.", "TBC izquierdo: dirección más directa a la cava superior y más lejos de la arteria subclavia, cómodo para el operador diestro desde el lado izquierdo; el conducto torácico desemboca en la unión con la subclavia (raro de puncionar).", "Subclavia infraclavicular: la clavícula da sombra y se pierde parte de la aguja; la guía entra de abajo hacia arriba (más riesgo de malposición). Sin ventajas frente al supraclavicular."], [["v_tbc1", "Maniobra para llegar al TBC: bajar con transversal manteniendo la VYI (a), inclinar hacia anterior (b), eje largo subclavia–TBC (c)"], ["v_tbc2", "TBC supraclavicular en plano: posición y aguja visible en la unión subclavia–TBC"]]], ["Vena axilar", ["Es la subclavia fuera del tórax: se evita la clavícula. Se ve en transversal y en longitudinal desde la línea axilar anterior. Se puede canalizar fuera de plano o en plano.", "Atención: arteria axilar y plexo braquial muy cerca; localizar la pleura."], [["v_axi", "Vena y arteria axilares: posición del transductor y vista transversal"]]], ["Vena femoral", ["Referencia: unión del tercio interno con el medio de la línea entre la sínfisis del pubis y la espina ilíaca anterosuperior. Deslizar el transductor transversal desde el ligamento inguinal hacia distal: vena medial, arteria lateral. Cuanto más distal, la vena se hace más profunda y la arteria se bifurca: más riesgo de punción arterial. Puncionar proximal a la bifurcación.", "Niño mayor: pierna en abducción y rotación externa. En el neonato esa maniobra aumenta la superposición vena–arteria: puncionar cerca del ligamento inguinal con la pierna neutra.", "En neonatos y lactantes la femoral es ~40% más chica que la VYI/TBC; se iguala a los ~3 años. Algunos grupos usan longitudinal en plano con 1/3 del transductor distal al ligamento y 2/3 proximal."], [["v_fem", "Arteria femoral superficial y profunda; vena femoral medial"], ["v_femlong", "Femoral longitudinal en plano"]]], ["PICC y catéter central de inserción periférica", ["Vena de elección: basílica en tercio medio del brazo (más gruesa, más profunda, menos trombosis, más cómoda; no limita la flexión del codo). Se canaliza guiada por ecografía en una zona no palpable.", "Venas braquiales: imagen de “Mickey Mouse” (dos venas braquiales laterales = orejas, arteria = cara). Pegadas a la arteria y al nervio braquial: alternativa menos adecuada. La cefálica es la más lateral y superficial: trayecto menos favorable para llegar a la punta.", "Técnica microseldinguer: aguja fina o angiocatéter → guía recta corta → microintroductor (pelable) → catéter con fiador cortado a medida. Longitud: desde el punto de punción hasta el 2.º–3.er espacio intercostal paraesternal derecho. Habitual: 3 Fr (vena ≥3 mm) en niños pequeños, 4 Fr en mayores.", "Punta ideal: tercio inferior de la VCS / unión cavo-atrial."], [["v_mickey", "Paquete braquial: arteria (roja), venas braquiales (azules), basílica (verde)"], ["v_picc", "Colocación de PICC en basílica: abordaje, medición y posición final"]]], ["Canalización arterial", ["Indicada para monitoreo invasivo de presión y gasometrías. La ecografía aumenta el éxito al primer intento, reduce hematomas, intentos y duración, sobre todo en hipoperfusión, edema, obesidad, variantes anatómicas o intentos fallidos.", "Radial (la más usada): hacer test de Allen. Muñeca en extensión ~45° (más extensión comprime el vaso; elegir la que da mayor calibre). Punción directa con angiocatéter a 15–30° respecto de la piel, avanzar hasta que la arteria se colapsa y se expande o refluya sangre; retirar presión del transductor para avanzar. Confirmar que el catéter está en la luz y no atravesó la pared posterior. Complicaciones frecuentes: hematoma, trombosis, infección (aumentan con los intentos).", "Femoral: sin circulación colateral pero de buen calibre; alternativa si la radial es difícil. Pierna en abducción y rotación externa. Ver el paquete (de lateral a medial: nervio, arteria, vena) y puncionar proximal a la bifurcación, a ~45°.", "Otras: dorsal del pie, axilar. Braquial: se desaconseja (sin colateral).", "En plano: transductor 2–3 cm proximal al punto de punción, ver avanzar el catéter todo el tiempo. Fuera de plano: arteria centrada en la pantalla y seguir la punta basculando."], []], ["Comprobar guía y punta del catéter", ["Guía: confirmarla dentro de la vena antes de dilatar. En subclavia/TBC verificar en eje largo supraclavicular y descartar que haya ido a la yugular o al TBC contralateral (rotar el cuello hacia el lado de punción antes de avanzar la guía). En PICC de brazo, descartar migración a yugular.", "Posición ideal de la punta: tercio inferior de la VCS. Evitar aurícula derecha (arritmias, taponamiento, falsa saturación venosa central por seno coronario); reservada para ECMO y algunas terapias de reemplazo renal. Evitar bifurcaciones y curvas vasculares. En catéteres de miembro inferior: justo por encima del diafragma, en la unión cavo-atrial.", "Femoral: se ve fácil la punta desde subcostal eje de cavas (VCI y aurícula derecha). Un operador puede ajustar la altura del catéter en tiempo real. Los catéteres superiores son más difíciles de ver.", "Protocolo CVC SONO (descartar malposición): 1) C de complicación: pulmón con lineal 2.º–4.º espacio, deslizamiento pleural para descartar neumotórax; 2) V de intravenoso: yugulares y subclavia/innominada bilaterales y VCI, para descartar migración; 3) C de intracardíaco: subcostal 4 cámaras o paraesternal eje corto.", "Localizar la punta en niños: subcostal eje de cavas (largo y corto); si no se ve la VCS, paraesternal derecho y supraesternal; si no aparece, buscar el catéter en yugulares y TBC. Concordancia con la radiografía de ~92% en la serie del grupo. Si hay duda o catéteres múltiples, confirmar con radiografía.", "Tras cualquier punción cervical o torácica: buscar deslizamiento pleural bilateral y líneas A/B (descartar neumotórax) y observar derrame pericárdico si hay inestabilidad.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP (Sociedad Española de Cuidados Intensivos Pediátricos)."], [["v_tip1", "Comprobación radiográfica y ecográfica de la punta (ejemplos de la guía)"], ["v_tip2", "Planos para localizar el catéter: subcostal VCI–aurícula, VCS, paraesternal derecho, yugular, subclavia"]]]]], ["Ecografía pulmonar", "heart", [["Sondas y técnica", ["Lineal de alta frecuencia (5–12 MHz): suficiente en pediatría y de elección en neonatos; muestra deslizamiento, líneas A y B. Convexa/microconvexa: mejor para zonas profundas (consolidación, derrame). Usar el preset de pulmón sin atenuadores de artefactos.", "Sonda perpendicular al espacio intercostal, marca hacia craneal, punto de la pantalla a la izquierda. Corte oblicuo (paralelo a la costilla) elimina la sombra costal. Explorar siempre regiones anterior, lateral y posterior de ambos lados.", "Solo se ven las lesiones que llegan a la pleura: todos los neumotórax y derrames, ~98,5% de las consolidaciones y el síndrome intersticial (difuso). Única limitación absoluta: enfisema subcutáneo. Relativas: obesidad, hematoma, apósitos.", "Patrones según relación aire/líquido: normal (negro, líneas A) → edema intersticial (líneas B) → edema alveolar/intersticial severo (blanco) → consolidación (gris)."], [["l_patron", "Patrones ecográficos del pulmón según la proporción de aire y líquido"], ["l_bat", "Signo del murciélago: dos costillas con sombra y línea pleural entre ellas"]]], ["Signos básicos", ["Deslizamiento pleural: descarta neumotórax en ese punto (sensibilidad cercana a 100%). En modo M: signo de la orilla de mar (olas = pared, arena = pulmón). Su ausencia no confirma neumotórax: también ocurre con intubación selectiva, atelectasia, SDRA, adherencias, PEEP alta, apnea.", "Pulso pulmonar: movimiento de la pleura sincrónico con el latido cuando no hay ventilación; equivale a deslizamiento (pleuras unidas), descarta neumotórax.", "Líneas A: horizontales, repetidas, reverberación de la pleura; indican aire. Con deslizamiento = pulmón normal.", "Líneas B: verticales, desde la pleura hasta el fondo, borran las líneas A y se mueven con el deslizamiento. Hasta 2 por espacio pueden ser normales. ≥3 por campo = positivo. Síndrome intersticial: ≥2 regiones positivas por lado y bilateral. Confluentes: pulmón blanco.", "Líneas Z (cortas, mal definidas, no borran A) y líneas E (superficiales a la pleura, enfisema subcutáneo o cuerpo extraño) no son líneas B.", "Código de barras / estratosfera (modo M): líneas por encima y por debajo de la pleura = sin deslizamiento.", "Punto pulmón: transición entre pulmón con deslizamiento y sin deslizamiento en la misma imagen: 100% específico de neumotórax, poco sensible. Con la ecografía se mide extensión, no volumen."], [["l_a", "Líneas A (rótulos en inglés)"], ["l_sea", "Orilla de mar (modo M): deslizamiento presente"], ["l_pulso", "Pulso pulmonar en modo M"], ["l_b", "Líneas B"], ["l_bconf", "Líneas B confluentes: pulmón blanco"], ["l_strat", "Estratosfera / código de barras (modo M): sin deslizamiento"], ["l_lp", "Punto pulmón en 2D y en modo M"]]], ["Derrame, consolidación y aireación", ["Derrame: imagen anecoica (cuadrada) limitada por pleura parietal, sombras costales y pleura visceral (signo del cuadrado); en modo M el pulmón se acerca a la pleura parietal con cada inspiración (signo del sinusoide). Buscar en zonas declives. Trasudado: siempre anecoico. Derrame ecogénico o con septos: siempre exudado. Para toracocentesis: marcar el punto con mayor distancia interpleural inspiratoria, observar varios ciclos y puncionar con el paciente en la misma posición.", "Consolidación: patrón de tejido (hepatización). Con broncograma aéreo. Estático = atelectasia obstructiva probable; dinámico (se mueve con la respiración) prácticamente descarta atelectasia y apoya neumonía. Disposición lineal paralela: atelectasia; arboriforme: neumonía. En bases, confirmar el diafragma para no confundir con vísceras. Signo del desflecamiento: borde profundo irregular (consolidación), a diferencia del derrame (borde regular y recto).", "Score de aireación: 12 zonas (superior e inferior de cara anterior, lateral y posterior de cada hemitórax). N=0, B1=1 (líneas B separadas 5–7 mm), B2=2 (B coalescentes), C=3 (consolidación). Máximo 36. En prueba de extubación con tubo en T: aumento >17 se asoció a distrés postextubación; ≤12 lo excluye (datos de adultos).", "Al subir PEEP en SDRA difuso: desaparecen las líneas B anteriores. Con patrón focal no sobrepasar PEEP 10. La ecografía no detecta hiperinsuflación (se ve como pulmón normal con líneas A)."], [["l_sin", "Derrame: signo del sinusoide en modo M"], ["l_bronc", "Consolidación con broncograma aéreo"], ["l_shred", "Signo del desflecamiento"], ["l_air", "Pérdida progresiva de aire: normal, intersticial, neumonía, atelectasia"]]], ["Neonato", ["Enfermedad por déficit de surfactante: pulmón blanco bilateral, pleura engrosada e irregular, consolidaciones pequeñas, sin áreas respetadas (spared areas). Se puede ver antes de la clínica.", "Taquipnea transitoria del recién nacido: líneas B compactas en campos inferiores y aspecto normal en superiores; pleura normal; punto de doble pulmón (patognomónico).", "Aspiración meconial: consolidaciones parcheadas, broncograma, neumotórax frecuente (buscar ausencia de deslizamiento y punto pulmón).", "Hipoplasia pulmonar: patrón normal con asimetría de tamaño."], [["l_eds", "Enfermedad por déficit de surfactante: pulmón blanco"], ["l_dlp", "Punto de doble pulmón en TTRN"]]]]], ["Vía aérea y diafragma", "wind", [["Intubación: tráquea o esófago", ["Sonda lineal o convexa transversal sobre la pared anterior del cuello, por encima de la escotadura supraesternal. Tráquea: línea hiperecogénica en U invertida con artefacto de reverberación detrás. El esófago está lateral e izquierdo y solo se ve si está ocupado.", "Tubo en tráquea: una sola columna de gas. Intubación esofágica: segunda columna de gas junto a la traqueal (doble columna).", "Intubación bronquial selectiva: tras ver una sola columna en tráquea, buscar deslizamiento pleural bilateral. Si solo hay deslizamiento derecho, el tubo está en el bronquio derecho; al retirarlo reaparece el deslizamiento izquierdo.", "Cuerdas vocales: sonda de alta frecuencia a través del cartílago tiroides. Dos estructuras triangulares hipoecoicas que se abren y cierran con la respiración; permite descartar paresia unilateral.", "Sagital: el tubo se ve como dos líneas paralelas en carril; no aporta mucho. Llenar el manguito con suero facilita ver el extremo caudal."], [["a_tr", "Tráquea normal (a través del cartílago tiroides)"], ["a_eso", "Intubación esofágica: tráquea sin tubo y esófago con tubo"], ["a_sag", "Vista sagital del tubo endotraqueal"]]], ["Diafragma", ["Sonda lineal: ventana entre 7.ª y 10.ª costilla, línea axilar posterior, marca hacia la axila. Convexa o sectorial: abordaje abdominal transhepático (derecho) y transesplénico (izquierdo). En lactantes se pueden ver ambos hemidiafragmas desde subcostal central.", "Excursión (modo M): normal si es >4 mm y la diferencia entre ambos lados es <50%. Sube hacia el transductor en la inspiración. El hemidiafragma izquierdo se mueve más que el derecho. En niños sanos depende de la edad y el peso (curvas de El-Halaby).", "Grosor: tres capas (pleura, músculo hipoecoico, peritoneo); engrosamiento de 2,5–3 mm en respiración normal.", "Fracción de engrosamiento TFdi = (grosor inspiratorio − espiratorio) ÷ espiratorio × 100. Normal ≥20% sin soporte ventilatorio; 30–40% en sanos en respiración espontánea. Medir solo en respiración espontánea con presión de soporte mínima.", "Parálisis: el hemidiafragma afectado casi no se mueve o se mueve de forma paradójica (sube en la inspiración si no se mueve activamente, baja en la espiración), con menor grosor. Diferencia >50% entre excursiones sugiere parálisis. Causa más frecuente: lesión del frénico tras cirugía cardíaca. Es operador dependiente; no usar como única evaluación."], [["d_m", "Movimiento diafragmático normal en modo M"], ["d_gro", "Grosor diafragmático (medición en 2D)"]]]]], ["Ecocardiografía funcional", "heart", [["Ventanas y sondas", ["Sonda sectorial (phased array) o microconvexa pediátrica 4–8 MHz hasta ~20–25 kg; sonda de adulto 1–5 MHz por encima. Modos esenciales: 2D, M, Doppler color, pulsado y continuo; Doppler tisular y ECG integrado son útiles. El icono de la sonda va en la esquina superior derecha de la pantalla (recomendación ASE).", "Paraesternal eje largo (PEL): 3.º–4.º espacio, marca al hombro derecho. Paraesternal eje corto (PEC) a nivel de papilares (marca al hombro izquierdo) y a nivel del pedículo vascular (inclinar hacia los pies). Apical 4 y 5 cámaras: ápex, marca a la axila izquierda. Subcostal 4 cámaras, eje corto y eje de cavas: marca a la axila izquierda / hombro izquierdo / cabeza.", "Usos principales: PEL y PEC función del VI y tracto de salida; A4C TAPSE, relación VD/VI, Doppler mitral, insuficiencia tricuspídea; A5C gasto cardíaco; subcostal derrame, shunts, VCI."], [["e_planos", "Planos de exploración del corazón"], ["e_pel", "Paraesternal eje largo"], ["e_pec", "Paraesternal eje corto, nivel papilares"], ["e_a4c", "Apical 4 cámaras"], ["e_s4c", "Subcostal 4 cámaras"], ["e_sec", "Subcostal eje corto"]]], ["Función del VI", ["Fracción de acortamiento (modo M en PEL o PEC) = (DdVI − DsVI) ÷ DdVI × 100. Normal 25–45%; leve 20–25%; moderada 15–20%; grave <15%.", "Fracción de eyección: Teicholz (asume geometría normal, no confiable en cardiopatías o dilatación) o Simpson (A4C, trazando el endocardio). Normal >60%; leve 40–50%; moderada 30–40%; grave <30%.", "Gasto cardíaco por Doppler: diámetro del TSVI en PEL (mesosístole) y integral velocidad-tiempo (IVT) del TSVI en A5C con ángulo <20°. VS = 0,785 × D² × IVT. GC = FC × VS. Índice cardíaco normal 3–5 L/min/m².", "Diástole: onda E 0,9 ± 0,15 m/s, onda A 0,4 ± 0,1 m/s; relación E/A >1 y <2 (en niños 2,3 ± 0,6). E/E′ <8 normal; >12 sugiere presión de AI >15 mmHg. Presión de AI elevada: AI dilatada, E/A >2, tiempo de desaceleración <180 ms."], [["e_ivt", "Gasto cardíaco: diámetro del TSVI (izq.), posición del Doppler en A5C (centro), IVT (der.)"], ["e_ea", "Doppler transmitral: ondas E y A"]]], ["Función y presiones del VD", ["Septo interventricular (PEC): tipo I normal (VI circular, VD en semiluna); tipo II aplanado (presiones iguales); tipo III desviado a la izquierda (VD > VI). Movimiento paradójico del septo: presión del VD > VI en sístole.", "TAPSE (modo M en A4C, borde lateral del anillo tricuspídeo): depende de edad y superficie corporal (curvas de Koestenberger). TAPSV >10 cm/s.", "Relación área VD/VI en A4C: <0,6 normal; 0,6–0,9 dilatación moderada; >0,9 grave (>1 = VD mayor que el VI).", "Presión pulmonar sistólica = 4 × (Vmáx de la regurgitación tricuspídea)² + PVC. Normal <30 mmHg; hipertensión pulmonar >40 mmHg. Solo si hay insuficiencia tricuspídea.", "Presión de aurícula derecha por VCI (solo en respiración espontánea): colapso >50% → PAD <10 mmHg; colapso <50% → PAD >10 mmHg; VCI dilatada sin variación → PAD >20 mmHg."], [["e_tapse", "TAPSE en modo M"], ["e_vdvi", "Relación VD/VI: <0,6 (izq.) y >1 (der.)"], ["e_vci", "VCI en modo M: diámetro máximo y mínimo"]]], ["Derrame pericárdico y taponamiento", ["Se ve como espacio anecoico entre las hojas del pericardio, primero en los segmentos inferiores y posteriores en decúbito supino. Ventanas más rentables: subcostal 4 cámaras, apical 4 cámaras y PEL.", "Taponamiento: depende de la cantidad y de la velocidad de acumulación. Colapso diastólico de la aurícula derecha primero y luego del VD (signo más sensible); cuanto más grave, más se extiende el colapso a la sístole. Variación respiratoria del llenado mitral (pulso paradójico ecográfico) es el signo más específico. VCI dilatada sin colapso. Corazón “bamboleante” (swinging heart) con derrame masivo.", "En ventilación mecánica la VCI dilatada no es diagnóstica."], [["e_derr", "Derrame pericárdico en 2D y modo M"], ["e_derr2", "Derrame pericárdico en subcostal"]]], ["Precarga y respuesta a fluidos", ["Área telediastólica del VI <5,5 cm²/m² predice respuesta a fluidos. Colapso sistólico de las paredes (kissing walls) en PEC: hipovolemia grave.", "Variación respiratoria de la velocidad pico sistólica aórtica (VVPs) = (máx − mín) ÷ promedio × 100. >12% predice respuesta a fluidos; el único parámetro consistente en niños según revisión sistemática. Puede medirse con ventilación mecánica sin esfuerzo o en respiración espontánea.", "Elevación pasiva de piernas: VS aumenta >12% en respondedores; sensibilidad baja en pediatría.", "Colapsabilidad de la VCS >36% y distensibilidad de la VCI >18%: validadas solo en adultos ventilados y relajados. Falsos positivos con fallo de VD o volumen corriente alto."], []]]], ["Otros procedimientos ecoguiados", "pulse", [["Drenaje torácico y toracocentesis", ["Riesgos de la técnica a ciegas: hemotórax, neumotórax y punción de hígado o bazo. La ecografía ayuda a elegir el punto, reduce complicaciones y confirma el resultado. Técnica estática: solo marcar el punto y puncionar sin mover al paciente. Técnica dinámica (más recomendable): ver la aguja en tiempo real.", "Sonda lineal de alta frecuencia sirve para todas las edades pediátricas. Funda y gel estériles. Marca de la sonda a craneal en corte longitudinal.", "Posición: paciente despierto, sentado inclinado hacia adelante con los brazos apoyados (el líquido se acumula en la zona subescapular). En decúbito: leve rotación lateral con el hemitórax afectado elevado, brazo del lado afectado sobre la cabeza, cabecera a 30–45°, exploración inicial en la línea axilar media. Mantener la posición entre el marcaje y la punción.", "Explorar toda la superficie disponible, de axila a paravertebral, hasta el diafragma. En colecciones loculadas el mejor punto puede no ser el de mayor acumulación. Identificar hígado, bazo y diafragma para evitarlos.", "Medir el espesor máximo con el calibrador. Evitar procedimientos sobre colecciones de menos de 10 mm (riesgo de punción pulmonar). No abordar si el pulmón o el diafragma invaden la ventana ecográfica durante el ciclo respiratorio.", "Semiología: colección hipo o anecoica entre las dos hojas pleurales; cambia de diámetro con la respiración; en modo M signo del sinusoide. Signo de la medusa: pulmón atelectásico flotando en un derrame grande. Septos o panal de abejas: exudado complicado.", "Técnica dinámica en plano: transductor longitudinal, aguja por el lado más anterior del tórax, avanzar hasta la profundidad media del derrame. Inclinar la base de la aguja hacia craneal para que la guía vaya hacia caudal; bascular el transductor junto con la aguja. Colocar el drenaje en la zona inferior y posterior.", "Al terminar: descartar neumotórax (deslizamiento pleural), comprobar la posición del tubo y cuantificar el derrame residual.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["p_pos", "Posición del paciente: despierto (zona subescapular) y en decúbito"], ["p_derr", "Derrame simple de ~1,5 cm de espesor máximo"], ["p_sin", "Signo del sinusoide en modo M"], ["p_aguja", "Inserción de la aguja en plano en el espacio pleural"]]], ["Paracentesis y catéter de diálisis peritoneal", ["Indicaciones: diagnóstica (trauma, sospecha de peritonitis) o terapéutica (compromiso respiratorio, compresión abdominal, colocación de catéter de diálisis). En pediatría las causas más frecuentes son insuficiencia renal y cardíaca.", "Material: sonda convexa 3–7 MHz (microconvexa 7–10 MHz en lactantes), funda y gel estériles, campo estéril, agujas 18–22 G, anestésico local, catéter de diálisis según peso si se usa Seldinger.", "Ascitis: líquido anecoico sobre las asas, que se mueven. Exudado, pus o hemoperitoneo: más ecogénico y granulado. La apariencia no distingue la naturaleza del líquido (a diferencia del derrame pleural).", "Buscar el líquido en los cuadrantes inferiores. Puntos de punción: línea media infraumbilical (entre el tercio superior y los dos inferiores) o en el cuadrante inferior, en la unión del tercio inferior con los dos tercios superiores de la línea ombligo–espina ilíaca anterosuperior.", "Localizar la arteria epigástrica inferior con Doppler color antes de puncionar (sobre todo en el lado izquierdo). Vaciar la vejiga antes (sondaje de descarga) para no puncionarla y mejorar la imagen.", "Punción directa perpendicular o en Z (traccionar la piel lateralmente y soltar al pasar la dermis, evita la fuga de líquido). Siempre con presión negativa. En plano si hay espacio; fuera de plano o en oblicuo en lactantes pequeños, siguiendo la trayectoria de la aguja.", "Confirmar con el líquido en la jeringa; si hay duda, instilar suero y verlo. Catéter de diálisis por Seldinger: comprobar guía y catéter hacia el fondo de saco de Douglas.", "Complicaciones <1–2%: hematoma de pared, fuga, sangrado (evitar la epigástrica), perforación intestinal (muy rara con eco), hipotensión por descompresión brusca (drenar lento), alteraciones electrolíticas (hiponatremia). Con eco es bastante segura incluso en trombopenia o coagulopatía leve a moderada.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["p_asc", "Ascitis anecoica sobre y entre las asas; hemoperitoneo más granulado"], ["p_ascpt", "Puntos de punción y relación con vejiga y vasos epigástricos"], ["p_epig", "Arteria epigástrica con Doppler color"], ["p_ascag", "Aguja en plano dentro del líquido ascítico"]]], ["Punción suprapúbica", ["Sobre todo en lactantes pequeños y neonatos para muestras estériles; también para catéter suprapúbico en trauma uretral o disfunción vesical. La ecografía localiza la vejiga llena y reduce complicaciones (hematuria, lesión intestinal) y aumenta el éxito.", "Material: convexa 3–7 MHz (microconvexa en lactantes), funda y gel estériles, aguja 18–22 G, jeringa, EMLA; catéter tipo Foley para Seldinger si es el caso.", "Transductor justo sobre la sínfisis del pubis, transversal (mejor orientación para puncionar). Previsualización breve y con gel precalentado: puede desencadenar la micción. Descartar asas intestinales anteriores a la vejiga.", "Posición: caderas en abducción con ayudante sujetando las piernas. Punción fuera de plano, perpendicular al abdomen, con presión negativa una vez dentro de la vejiga. Sedoanalgesia si se va a colocar catéter.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["p_vej", "Vejiga llena (izq.) y vacía (der.)"], ["p_vejpos", "Posición del lactante y lugar de punción"]]], ["Control de sondas", ["Vesical: ver el balón dentro de la vejiga; útil ante un Foley obstruido (se puede desobstruir con la vejiga llena a la vista) y para evitar manipulaciones innecesarias. Transversal sobre la sínfisis.", "Gástrica y transpilórica: técnica compleja, requiere entrenamiento y hoy es solo una alternativa a la radiografía. Paciente en decúbito supino lateralizado a la izquierda, sonda longitudinal con marca a craneal; buscar esófago abdominal y fundus bajo el hígado. Instilar suero agitado ayuda. Para el píloro y el duodeno lateralizar hacia la derecha.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["p_son", "Sonda en el tracto digestivo"]]], ["Pericardiocentesis", ["Poco frecuente en el niño, algo más en el postoperatorio de cirugía cardíaca. Urgente (taponamiento) o programada (derrame subagudo con repercusión). Con ecocardiografía las complicaciones bajaron mucho. Sonda de baja frecuencia (2–5 MHz, phased array o convexa), asepsia estricta, sedoanalgesia, monitor de ECG.", "Previsualizar en subcostal, apical y paraesternal (eje corto y largo) para ver localización, tamaño y distribución. Posición: supino con cabecera a 30–45°. Elegir el sitio donde el derrame está más cerca del transductor y es máximo, sin interponer miocardio, pulmón ni hígado.", "Subxifoideo: el más habitual; accede a derrames cercanos al VD sin estructuras vitales entre la piel y el saco; el saco suele estar a 5–8 cm. No sirve para derrames apicales.", "Apical: para derrames del ápex. Evitar el paquete vasculonervioso costal (borde inferior de la costilla). Cabecera a 30–45° y leve decúbito lateral izquierdo. Requiere experiencia; sin entrenamiento y salvo riesgo vital es preferible una ventana pericárdica quirúrgica.", "Paraesternal: evitar la arteria mamaria interna (se identifica con Doppler). La técnica eco-guiada en tiempo real es la más recomendada.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["p_pc1", "Abordaje subxifoideo"], ["p_pc2", "Abordaje paraesternal: evitar la arteria mamaria interna"], ["p_pc3", "Aguja entrando al derrame desde el abordaje apical o paraesternal"], ["p_pc4", "Derrame pericárdico: planos de referencia"]]], ["Punción lumbar", ["Indicaciones: diagnósticas (infección del SNC, metabolopatías, hipertensión intracraneal benigna, Guillain-Barré, infiltración) o terapéuticas (quimioterapia intratecal, drenaje de LCR, catéteres epidurales). La ecografía disminuye las punciones fallidas, traumáticas y las que requieren redirigir la aguja.", "Sonda lineal de alta frecuencia, asepsia estricta, funda y gel estériles. En neonatos y lactantes pequeños, por la osificación incompleta, se ven piel, espacio epidural, canal y cuerpos vertebrales.", "Medir: espacio interespinoso externo (el que se palpa) e interno (por donde debe pasar la aguja), ángulo de entrada (cuanto más recto, más fácil), profundidad hasta el espacio subaracnoideo y espesor del espacio subaracnoideo por debajo del cono medular. Elegir la postura donde ese espesor es máximo.", "Corte transversal: marcar el punto medio entre las apófisis espinosas y el nivel. Técnica estática (marcar) o dinámica (aguja en tiempo real).", "Detecta hematomas epidurales o subdurales por punciones previas que hacen fútil insistir.", "En niños mayores y adultos solo se ven las apófisis espinosas y el espacio epidural: sirve para marcar la línea media y el nivel.", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["p_lp1", "Visión sagital del canal espinal"], ["p_lp2", "Corte transversal en neonato o lactante"], ["p_lp3", "Distancia entre apófisis espinosas"], ["p_lp4", "Anatomía vertebral y corte"]]]]], ["eFAST pediátrico y ascitis", "pulse", [["eFAST en el niño politraumatizado", ["Estudio secuencial para detectar líquido libre (sangre) en peritoneo, pericardio y tórax. Mínimo detectable ≈100 mL. Línea más declive: pelvis en lactantes pequeños y fosa de Morison en niños mayores.", "Sondas: baja frecuencia convexa/microconvexa/sectorial para abdomen; lineal de alta frecuencia para pleura. Preferible una sola sonda (la sectorial es multipropósito) para no perder tiempo.", "En el inestable: empezar por el tórax (línea medioclavicular, neumotórax) y las bases por la línea axilar posterior (hemotórax). Luego: 1) pericárdica subxifoidea (4 cámaras, ajustar profundidad), 2) perihepática (Morison, polo inferior del riñón y espacio subdiafragmático), 3) periesplénica (más difícil por el estómago y el bazo; empezar en la línea axilar posterior), 4) pelvis (transversal y longitudinal, antes de sondar).", "Trendelenburg aumenta la sensibilidad en las áreas perihepática y periesplénica; anti-Trendelenburg en la pelvis. Hacer un barrido completo de la interfase hígado–riñón: una sola imagen puede no mostrar líquido.", "Limitaciones: sensibilidad baja en pediatría (45–65%, hasta 40% de las lesiones parenquimatosas son encapsuladas); especificidad ~95%. Si hay líquido libre: TC urgente (o cirugía si hay inestabilidad refractaria). Un FAST negativo no excluye lesión: repetirlo en serie (sube la sensibilidad hasta ~85%) y combinar con clínica y laboratorio (transaminasas). El contraste ecográfico mejora la detección pero no está aprobado en niños en Europa.", "No confundir vejiga, vesícula, grandes vasos o artefactos de espejo con líquido libre. Contorno muy irregular: líquido entre asas intestinales.", "Otras aplicaciones: confirmar intubación, contusión pulmonar, función y volemia (corazón, cava), accesos vasculares, Doppler transcraneal y vaina del nervio óptico, neumoperitoneo, fracturas (disrupción de la cortical), cuerpos extraños (hiperecogénicos; madera y plástico dan sombra, el metal reverberación).", "Fuente: Grupo de Trabajo de Ecografía de la SECIP."], [["f_areas", "Áreas de exploración del abdomen"], ["f_pericardio", "Hemopericardio desde el subxifoides"], ["f_hepato_pos", "Posición de la sonda perihepática"], ["f_hepato", "Fosa de Morison con líquido"], ["f_bazo_pos", "Posición de la sonda periesplénica"], ["f_bazo", "Espacio esplenorrenal"], ["f_pelvis_pos", "Posición de la sonda en pelvis"], ["f_vejiga", "Vejiga en corte axial"], ["f_vejiga_liq", "Líquido libre alrededor de la vejiga"]]]]], ["Fundamentos de ecografía", "calc", [["Principios físicos", ["Ultrasonido: >20.000 Hz. Los ecógrafos usan 1–20 MHz. Longitud de onda λ = velocidad ÷ frecuencia (inversamente proporcional). Más frecuencia = más resolución y menos penetración.", "Alta frecuencia (>5 MHz): penetra <5 cm, para vasos, músculo, pleura, ojos. Baja frecuencia (1–5 MHz): penetra >5 cm, para tórax profundo y abdomen.", "Velocidad en tejidos (m/s): grasa 1470, músculo 1568, hígado 1540, hueso 3600, agua 1492, aire 332. Impedancia = velocidad × densidad. Mayor diferencia de impedancia entre dos medios = más reflexión. Reflexión: tejido blando/aire 99%, grasa/hueso 50%, tejido blando/agua (gel) 0,2%. Por eso el gel elimina el aire.", "Mantener el haz lo más perpendicular posible a la estructura para reducir artefactos. Atenuación: a mayor frecuencia y mayor impedancia, menor penetración.", "Escala de grises: anecoico (líquido) → hipoecoico (grasa, órganos) → ecoico → hiperecoico (músculo, aire, hueso)."], []], ["Artefactos", ["Sombra acústica posterior: zona negra tras estructuras que reflejan todo (hueso, calcio, metal).", "Refuerzo acústico posterior: zona hiperecogénica tras estructuras anecoicas (líquido).", "Cola de cometa (líneas B en el pulmón): rayo láser desde una interfase muy ecogénica (pleura, peritoneo).", "Reverberación (líneas A en el pulmón): líneas paralelas repetidas por rebote entre sonda e interfase (pulmón, tubo digestivo).", "Espejo: imagen falsa de una estructura real, frecuente en el diafragma.", "Anisotropía: los tendones cambian de brillo según la angulación del haz."], []], ["Modos y controles", ["2D (modo B): imagen bidimensional en escala de grises, dinámica en tiempo real. Modo M: un solo haz a lo largo del tiempo (movimiento).", "Doppler color: asigna color según dirección y velocidad del flujo. Power Doppler: solo presencia de flujo (detecta flujos lentos). Doppler pulsado: velocidad en un punto; corregir el ángulo de insonación (idealmente ≤15–20°). Doppler continuo: velocidades altas a lo largo de todo el haz.", "Controles: encendido, datos del paciente, preset (tipo de examen), sonda, marca (muesca), congelar, cineloop, guardar, profundidad, zoom, foco, ganancia (brillo; TGC por profundidad), ángulo, ventana de muestreo y PRF (escala de velocidad). Ganancia de color alta produce ruido o aliasing.", "Sondas: lineal (alta frecuencia, baja profundidad: vasos, pleura, piel, ojos); convexa (baja frecuencia, alta profundidad: abdomen, tórax); sectorial (baja frecuencia: corazón, tórax, neuro-eco).", "Cuidados: retirar el gel con paño de papel; limpiar y desinfectar con los productos del fabricante (evitar abrasivos y en general alcohol); no pasar las ruedas por el cable; limpiar el equipo después de cada paciente."], []]]]]);
let h=S.map((s,k)=>card("pc-"+k,s[0],s[1],s[2].length,s[2].map(blk).join(""))).join("");
h+=card("pc-sum","Cuadro resumen por vista","list",SUM.length,SUM.map(blk).join(""));
h+=card("pc-notas","Notas de la unidad (La Biblia)","pulse",NOTAS.length,NOTAS.map(blk).join(""));
h+=card("pc-ref","Referencias de la guía","book",REFS.length,`<div class="bk">${REFS.map((r,i)=>`<p>${i+1}. ${esc(r)}</p>`).join("")}</div>`);
const hn=`<p class="chint">Las secciones de accesos vasculares, ecografía pulmonar, vía aérea y diafragma y ecocardiografía funcional son un resumen de las guías del Grupo de Trabajo de Ecografía de la SECIP (con sus imágenes; rótulos en español o inglés según el original; población pediátrica). Resumen y traducción al español de la guía “FAST Scan-eFAST Ultrasound Exam Made Easy: Step-By-Step Guide”, de POCUS 101 (pocus101.com). Autores principales: Seth White y Vi Dinh. Las imágenes son de esa guía, incluidas para uso personal sin conexión; los rótulos dentro de las imágenes están en inglés. La fuente está basada en población adulta. Es una ayuda de consulta: no reemplaza la formación ni la acreditación en ecografía ni el criterio clínico.</p>`;
$("#pc").innerHTML=h+'<div id="pc-ck"></div>'+hn;
$("#pc-ck").innerHTML=ckHtml(CK.find(c=>c[0]=="pocusq"),"p");CK.filter(c=>c[0]=="pocusq").forEach(c=>upd(c[0]));
