["#pc","#tpl"].forEach(s=>$(s).addEventListener("click",e=>{const i=e.target.closest("figure.us img");if(!i)return;$("#pz-i").src=i.src;$("#pz-i").alt=i.alt;$("#pz-i").className="";$("#pz-t").textContent=i.alt;z.hidden=false;document.body.style.overflow="hidden"}));
