const wt=()=>parseFloat(E("b-w").value),ht=()=>parseFloat(E("b-h").value);
function palms(){return Math.max(0,parseFloat(E("b-np").value)||0)}
/* ===== Pintura con el dedo sobre la silueta ===== */
const SC=2,WU=200,mx=p=>[WU-p[0],p[1]];
function spl(P){const n=P.length,p=new Path2D(),q=P.map(a=>[a[0]*SC,a[1]*SC]);p.moveTo(q[0][0],q[0][1]);for(let i=0;i<n;i++){const a=q[(i-1+n)%n],b=q[i],c=q[(i+1)%n],d=q[(i+2)%n];p.bezierCurveTo(b[0]+(c[0]-a[0])/6,b[1]+(c[1]-a[1])/6,c[0]-(d[0]-b[0])/6,c[1]-(d[1]-b[1])/6,c[0],c[1])}p.closePath();return p}
function cr(p,P,first){const n=P.length;if(first)p.moveTo(P[0][0],P[0][1]);else p.lineTo(P[0][0],P[0][1]);for(let i=0;i<n-1;i++){const a=P[Math.max(i-1,0)],b=P[i],c=P[i+1],d=P[Math.min(i+2,n-1)];p.bezierCurveTo(b[0]+(c[0]-a[0])/6,b[1]+(c[1]-a[1])/6,c[0]-(d[0]-b[0])/6,c[1]-(d[1]-b[1])/6,c[0],c[1])}}
function limb(pts){const n=pts.length,L=[],R=[];for(let i=0;i<n;i++){const a=pts[Math.max(i-1,0)],b=pts[i],c=pts[Math.min(i+1,n-1)];let dx=c[0]-a[0],dy=c[1]-a[1];const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;const w=b[2]/2;L.push([(b[0]-dy*w)*SC,(b[1]+dx*w)*SC]);R.push([(b[0]+dy*w)*SC,(b[1]-dx*w)*SC])}
 const p=new Path2D();cr(p,L,true);cr(p,R.reverse(),false);p.closePath();return p}
const ell=(cx,cy,rx,ry)=>{const p=new Path2D();p.ellipse(cx*SC,cy*SC,rx*SC,ry*SC,0,0,Math.PI*2);return p};
const sym=(left,bot,top)=>left.concat(bot,left.slice().reverse().map(mx),top);
